-- Owner approved users + shared identity writer containment, 2026-10-21.
-- Target lvnvkpyxtuilhrabtlwv; only one table and two function ACLs.
-- Exact core catalog guards; all other public/auth catalogs held unchanged in transaction.
BEGIN; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
DO $identity_containment$
DECLARE actual jsonb; outside_before jsonb; outside_after jsonb;
BEGIN
 SELECT evidence INTO outside_before FROM (WITH outside_relations AS (SELECT n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,c.relacl::text AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth') AND c.oid<>'public.users'::regclass), all_policies AS(SELECT * FROM pg_policies WHERE schemaname IN ('public','auth')), other_functions AS(SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS args,p.prosecdef,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,p.proconfig,md5(pg_get_functiondef(p.oid)) AS definition_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth') AND p.prokind='f' AND NOT(p.oid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure]))) SELECT jsonb_build_object('outside_relations_count',(SELECT count(*) FROM outside_relations),'outside_relation_hash',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY nspname,relname)::text) FROM outside_relations r),'all_policy_hash',(SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname)::text) FROM all_policies p),'other_function_hash',(SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY nspname,proname,args)::text) FROM other_functions f),'full_membership_hash',(SELECT md5(jsonb_agg(to_jsonb(m) ORDER BY roleid,member,grantor)::text) FROM pg_auth_members m),'full_role_hash',(SELECT md5(jsonb_agg((to_jsonb(r)-'rolvaliduntil') ORDER BY rolname)::text) FROM pg_roles r),'schema_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname)::text) FROM pg_namespace WHERE nspname NOT LIKE 'pg_temp_%' AND nspname NOT LIKE 'pg_toast_temp_%'),'default_acl_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY oid)::text,'[]')) FROM pg_default_acl a)) AS evidence) o;
 -- APPROVED_OUTSIDE_BASELINE_BEGIN
 IF outside_before IS DISTINCT FROM '{"all_policy_hash":"7e9cb774762c676316527c55b0d293b2","default_acl_hash":"44a28cc039b3dcbcf89869ea4f81c94a","full_membership_hash":"ccf4bdd3d6332379ba2ccec6d7cdc74b","full_role_hash":"23c7fa4ddfda46403dba4854ff221d8b","other_function_hash":"a5e66f2c5802c4fd295f365dd10c946b","outside_relation_hash":"14c3c85b0f304e930a81a923facf32e6","outside_relations_count":2673,"schema_acl_hash":"f92a57c8a6d85218d05ec4675ba5efbf"}'::jsonb THEN RAISE EXCEPTION 'identity precondition: approved outside catalog/dependency drift'; END IF;
 -- APPROVED_OUTSIDE_BASELINE_END
 SELECT evidence INTO actual FROM (SELECT (evidence - ARRAY['views','defaults','user_referring_definers','memberships']) || jsonb_build_object(
 'memberships',coalesce((SELECT jsonb_agg(m - 'grantor' ORDER BY m->>'role',m->>'member') FROM jsonb_array_elements(evidence->'memberships') m),'[]'::jsonb),
 'writers',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text,
 'grants',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'superuser',r.rolsuper,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE'),'grant_option',has_function_privilege(r.oid,p.oid,'EXECUTE WITH GRANT OPTION')) ORDER BY r.rolname) FROM pg_roles r WHERE rolname<>'acl_rehearsal_superuser')) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.oid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure])),
 'client_privileges',(SELECT jsonb_agg(jsonb_build_object('role',r.role,'privilege',p.privilege,'effective',has_table_privilege(r.role,'public.users',p.privilege)) ORDER BY r.role,p.privilege) FROM (VALUES('anon'),('authenticated'))r(role) CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN'))p(privilege)),
 'client_column_privileges',(SELECT jsonb_agg(jsonb_build_object('role',r.role,'column',a.attname,'privilege',p.privilege,'effective',has_column_privilege(r.role,a.attrelid,a.attnum,p.privilege)) ORDER BY r.role,a.attnum,p.privilege) FROM (VALUES('anon'),('authenticated'))r(role) CROSS JOIN pg_attribute a CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('REFERENCES'))p(privilege) WHERE a.attrelid='public.users'::regclass AND a.attnum>0 AND NOT a.attisdropped)
) AS evidence FROM (WITH target AS (SELECT c.* FROM pg_class c WHERE c.oid='public.users'::regclass),
columns AS (
 SELECT a.attnum,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS not_null,
 a.attidentity,a.attgenerated,a.attacl::text AS acl,pg_get_expr(ad.adbin,ad.adrelid) AS default_expression
 FROM target t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped
 LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
), functions AS (
 SELECT DISTINCT p.oid,n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,
 pg_get_userbyid(p.proowner) AS owner,p.prosecdef AS security_definer,p.proacl::text AS acl,p.proconfig,pg_get_functiondef(p.oid) AS definition
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE p.prokind='f' AND (p.oid IN(SELECT t.tgfoid FROM pg_trigger t WHERE t.tgrelid='public.users'::regclass AND NOT t.tgisinternal)
 OR (n.nspname='public' AND p.proname IN ('current_user_role','current_tenant_id','get_auth_tenant_id','is_admin','is_hq_super_admin'))
 OR (n.nspname='auth' AND p.proname IN ('uid','jwt')))
), dependent_views AS (
 SELECT DISTINCT n.nspname AS schema,v.relname AS name,v.reloptions,pg_get_userbyid(v.relowner) AS owner,
 has_table_privilege('anon',v.oid,'UPDATE') AS anon_update,has_table_privilege('authenticated',v.oid,'UPDATE') AS authenticated_update,
 has_table_privilege('anon',v.oid,'INSERT') AS anon_insert,has_table_privilege('authenticated',v.oid,'INSERT') AS authenticated_insert,
 has_table_privilege('anon',v.oid,'DELETE') AS anon_delete,has_table_privilege('authenticated',v.oid,'DELETE') AS authenticated_delete,
 pg_get_viewdef(v.oid,true) AS definition
 FROM pg_depend dep JOIN pg_rewrite rw ON rw.oid=dep.objid JOIN pg_class v ON v.oid=rw.ev_class JOIN pg_namespace n ON n.oid=v.relnamespace
 WHERE dep.refobjid='public.users'::regclass AND v.relkind IN('v','m') AND v.oid<>'public.users'::regclass
)
SELECT jsonb_build_object(
 'table',(SELECT jsonb_build_object('name',t.relname,'kind',t.relkind,'owner',pg_get_userbyid(t.relowner),'rls',t.relrowsecurity,'force_rls',t.relforcerowsecurity,'acl',t.relacl::text) FROM target t),
 'grants',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM target t CROSS JOIN LATERAL aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) a),
 'columns',(SELECT jsonb_agg(to_jsonb(c) ORDER BY attnum) FROM columns c),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conname) FROM pg_constraint c WHERE c.conrelid='public.users'::regclass),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',i.indexname,'definition',i.indexdef) ORDER BY i.indexname) FROM pg_indexes i WHERE i.schemaname='public' AND i.tablename='users'),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname) FROM pg_policies p WHERE schemaname='public' AND tablename='users'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid='public.users'::regclass AND NOT t.tgisinternal),
 'functions',(SELECT jsonb_agg(to_jsonb(f)-'oid' ORDER BY f.schema,f.name,f.arguments) FROM functions f),
 'views',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY schema,name) FROM dependent_views v),'[]'::jsonb),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'can_login',r.rolcanlogin) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN('anon','authenticated','service_role','postgres')),
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'grantor',pg_get_userbyid(m.grantor),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)) FROM pg_auth_members m WHERE pg_get_userbyid(m.member) IN('anon','authenticated')),'[]'::jsonb),
 'user_referring_definers',coalesce((SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN('pg_catalog','information_schema') AND p.prokind='f' AND p.prosecdef AND (p.prosrc ~* '\musers\M' OR p.prosrc ~* '\mEXECUTE\M')),'[]'::jsonb),
 'schema_grants',(SELECT jsonb_agg(jsonb_build_object('role',r.role,'usage',has_schema_privilege(r.role,'public','USAGE'),'create',has_schema_privilege(r.role,'public','CREATE')) ORDER BY r.role) FROM (VALUES('anon'),('authenticated'),('service_role'))r(role)),
 'defaults',coalesce((SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(a.defaclrole),'namespace',coalesce(n.nspname,''),'type',a.defaclobjtype,'acl',a.defaclacl::text) ORDER BY pg_get_userbyid(a.defaclrole),coalesce(n.nspname,''),a.defaclobjtype) FROM pg_default_acl a LEFT JOIN pg_namespace n ON n.oid=a.defaclnamespace WHERE n.nspname='public' OR a.defaclnamespace=0),'[]'::jsonb)
) AS evidence) b) c;
 IF actual IS DISTINCT FROM '{"client_column_privileges":[{"column":"id","effective":true,"privilege":"INSERT","role":"anon"},{"column":"id","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"id","effective":true,"privilege":"SELECT","role":"anon"},{"column":"id","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"email","effective":true,"privilege":"INSERT","role":"anon"},{"column":"email","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"email","effective":true,"privilege":"SELECT","role":"anon"},{"column":"email","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"full_name","effective":true,"privilege":"INSERT","role":"anon"},{"column":"full_name","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"full_name","effective":true,"privilege":"SELECT","role":"anon"},{"column":"full_name","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"phone","effective":true,"privilege":"INSERT","role":"anon"},{"column":"phone","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"phone","effective":true,"privilege":"SELECT","role":"anon"},{"column":"phone","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"role","effective":true,"privilege":"INSERT","role":"anon"},{"column":"role","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"role","effective":true,"privilege":"SELECT","role":"anon"},{"column":"role","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"avatar_url","effective":true,"privilege":"INSERT","role":"anon"},{"column":"avatar_url","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"avatar_url","effective":true,"privilege":"SELECT","role":"anon"},{"column":"avatar_url","effective":true,"privilege":"UPDATE","role":"anon"},{"column":"status","effective":true,"privilege":"INSERT","role":"anon"},{"column":"status","effective":true,"privilege":"REFERENCES","role":"anon"},{"column":"status","effective":true,"privilege