":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"updated_at","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"updated_at","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"base_salary","effective":true,"privilege":"INSERT","role":"authenticated"},{"column":"base_salary","effective":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"base_salary","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"base_salary","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"hire_date","effective":true,"privilege":"INSERT","role":"authenticated"},{"column":"hire_date","effective":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"hire_date","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"hire_date","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"resignation_date","effective":true,"privilege":"INSERT","role":"authenticated"},{"column":"resignation_date","effective":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"resignation_date","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"resignation_date","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"metadata","effective":true,"privilege":"INSERT","role":"authenticated"},{"column":"metadata","effective":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"metadata","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"metadata","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"position_tier","effective":true,"privilege":"INSERT","role":"authenticated"},{"column":"position_tier","effective":true,"privilege":"REFERENCES","role":"authenticated"},{"column":"position_tier","effective":true,"privilege":"SELECT","role":"authenticated"},{"column":"position_tier","effective":true,"privilege":"UPDATE","role":"authenticated"},{"column":"leave_balance",