": \"email\", \"providers\": [\"email\"]}''::jsonb,\n    jsonb_build_object(''full_name'', p_full_name, ''email_verified'', true),\n    NOW(),\n    NOW()\n  );\n\n  -- Insert into auth.identities (excluding email)\n  INSERT INTO auth.identities (\n    id,\n    provider_id,\n    user_id,\n    identity_data,\n    provider,\n    last_sign_in_at,\n    created_at,\n    updated_at\n  ) VALUES (\n    gen_random_uuid(),\n    v_user_id::text,\n    v_user_id,\n    jsonb_build_object(''sub'', v_user_id::text, ''email'', p_email, ''email_verified'', true, ''phone_verified'', false),\n    ''email'',\n    NOW(),\n    NOW(),\n    NOW()\n  );\n\n  RETURN v_user_id;\nEND;\n$function$\n","grants":[{"grantable":false,"grantee":"PUBLIC","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"bella_migration_executor","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}],"owner":"postgres","roles":[{"execute":true,"grant_option":false,"name":"anon","superuser":false},{"execute":true,"grant_option":false,"name":"authenticated","superuser":false},{"execute":true,"grant_option":false,"name":"authenticator","superuser":false},{"execute":true,"grant_option":false,"name":"bella_developer","superuser":false},{"execute":true,"grant_option":false,"name":"bella_migration_executor","superuser":false},{"execute":true,"grant_option":false,"name":"cli_login_postgres","superuser":false},{"execute":true,"grant_option":false,"name":"dashboard_user","superuser":false},{"execute":true,"grant_option":false,"name":"pg_checkpoint","superuser":false},{"execute":true,"grant_option":false,"name":"pg_create_subscription","superuser":false},{"execute":true,"grant_option