ue,"grant_option":false,"name":"verification_executor","superuser":false}],"security_definer":true,"signature":"create_onboarding_user(text,text,text)"},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","config":null,"definition":"CREATE OR REPLACE FUNCTION public.onboard_tenant(p_spa_name text, p_contact_phone text, p_address text, p_email text, p_admin_id uuid, p_admin_email text, p_admin_name text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_tenant_id UUID;\n    v_package_id UUID;\n    v_ktv_id UUID;\n    v_customer_id UUID;\n    v_booking_id UUID;\n    v_role_permissions JSONB;\n    v_salary_config JSONB;\n    v_coa_count INTEGER;\nBEGIN\n    -- 1. Check email duplicate\n    IF EXISTS (SELECT 1 FROM public.users WHERE email = p_admin_email) THEN\n        RAISE EXCEPTION ''Email % đã tồn tại trong hệ thống.'', p_admin_email;\n    END IF;\n\n    -- 2. Default configs (Updated to include ktv_lead, admin_staff, accountant, and hr)\n    v_role_permissions := ''{\"ktv_lead\": {\"dashboard\": true, \"customers\": false, \"bookings\": true, \"sessions\": true, \"chat\": true, \"crm\": true, \"services\": true, \"finance\": false, \"reconciliation\": false, \"inventory\": false, \"salary\": false, \"audit\": false, \"settings\": false},\n                            \"admin_staff\": {\"dashboard\": true, \"customers\": true, \"bookings\": true, \"sessions\": true, \"chat\": true, \"crm\": true, \"services\": true, \"inventory\": true, \"finance\": true, \"reconciliation\": false, \"salary\": false, \"audit\": false, \"settings\": false},\n                            \"accountant\": {\"dashboard\": true, \"customers\": false, \"bookings\": false, \"sessions\": false, \"chat\": false, \"crm\": false, \"services\": true, \"inventory\": true, \"finance\": true, \"reconciliation\": true, \"salary\": true, \"audit\": false, \"settings\": false},\n                            \"hr\": {\"dashboard\": true, \"customers\": false, \"bookings\": false, \"sessions\": true, \"chat\": false, \"crm\": false, \"services\": false, \"inventory\": false, \"finance\": false, \"reconciliation\": false, \"salary\": true, \"audit\": false, \"settings\": false}}''::jsonb;\n    v_salary_config := ''{\"bonus_5_star\": 50000, \"bonus_4_5_star\": 30000, \"bonus_4_star\": 10000, \"kpi_target_sessions\": 30, \"kpi_bonus_amount\": 1000000}''::jsonb;\n\n    -- 3. Create tenant\n    INSERT INTO public.tenants (\n        name, contact_phone, address, email, status, role_permissions, salary_config\n    )\n    VALUES (\n        p_spa_name, p_contact_phone, p_address, p_email, ''active'', v_role_permissions, v_salary_config\n    )\n    RETURNING id INTO v_tenant_id;\n\n    -- 4. Create admin user\n    INSERT INTO public.users (id, email, full_name, role, status, tenant_id)\n    VALUES (p_admin_id, p_admin_email, p_admin_name, ''admin'', ''active'', v_tenant_id);\n\n    -- 5. Seed sample package\n    INSERT INTO public.packages (\n        name, description, price, full_price, duration, total_sessions, ktv_commission, status, tenant_id\n    )\n    VALUES (\n        ''Massage Bầu VIP Nhật Bản'',\n        ''Gói chăm sóc massage bầu cao cấp theo liệu trình Nhật Bản giúp thư giãn cơ thể và giảm stress cho mẹ.'',\n        1200000, 1200000, ''90 phút/buổi'', 10, 150000, ''active'', v_tenant_id\n    )\n    RETURNING id INTO v_package_id;\n\n    -- 6. Seed sample KTV\n    v_ktv_id := uuid_generate_v4();\n    INSERT INTO public.users (id, email, full_name, role, status, tenant_id)\n    VALUES (\n        v_ktv_id,\n        ''ktv.mau.'' || substring(v_tenant_id::text from 1 for 8) || ''@bellaspa.com.vn'',\n        ''Trần Thị Mai (KTV Mẫu)'', ''ktv'', ''active'', v_tenant_id\n    );\n\n    -- 7. Seed sample customer\n    INSERT INTO public.customers (phone, name_mother, name_baby, dob_baby, address, status, tenant_id)\n    VALUES (\n        ''0987'' || substring(v_tenant_id::text from 1 for 6),\n        ''Phạm Thu Hương (Khách Mẫu)'', ''Bé Bơ'',\n        CURRENT_DATE - INTERVAL ''10 days'', p_address, ''active'', v_tenant_id\n    )\n    RETURNING id INTO v_customer_id;\n\n    -- 8. Seed sample booking\n    INSERT INTO public.bookings (\n        booking_number, customer_id, package_id, status, deposit_amount, full_price,\n        start_date, end_date, total_sessions, completed_sessions, contract_signed,\n        assigned_ktv_id, tenant_id\n    )\n    VALUES (\n        ''BK-'' || UPPER(substring(v_tenant_id::text from 1 for 5)),\n        v_customer_id, v_package_id, ''booked'', 200000, 1200000,\n        CURRENT_DATE, CURRENT_DATE + INTERVAL ''10 days'', 10, 0, TRUE,\n        v_ktv_id, v_tenant_id\n    )\n    RETURNING id INTO v_booking_id;\n\n    -- 9. Seed default Chart of Accounts (Thông tư 133)\n    BEGIN\n        v_coa_count := public.seed_default_coa(v_tenant_id);\n        RAISE NOTICE ''[onboard_tenant] Seeded % accounting accounts for tenant %'', v_coa_count, v_tenant_id;\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING ''[onboard_tenant] Failed to seed COA for tenant %: %'', v_tenant_id, SQLERRM;\n    END;\n\n    -- 10. Auto-create accounting period cho tháng hiện tại\n    BEGIN\n        PERFORM public.ensure_open_period(v_tenant_id, CURRENT_DATE);\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING ''[onboard_tenant] Failed to create accounting period for tenant %: %'', v_tenant_id, SQLERRM;\n    END;\n\n    RETURN v_tenant_id;\nEND;\n$function$\n","grants":[{"grantable":false,"grantee":"PUBLIC","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"bella_migration_executor","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}],"owner":"postgres","roles":[{"execute":true,"grant_option":false,"name":"anon","superuser":false},{"execute":true,"grant_option":false,"name":"authenticated","superuser":false},{"execute":true,"grant_option":false,"name":"authenticator","superuser":false},{"execute":true,"grant_option":false,"name":"bella_developer","superuser":false},{"execute":true,"grant_option":false,"name":"bella_migration_executor","superuser":false},{"execute":true,"grant_option":false,"name":"cli_login_postgres","superuser":false},{"execute":true,"grant_option":false,"name":"dashboard_user","superuser":false},{"execute":true,"grant_option":false,"name":"pg_checkpoint","superuser":false},{"execute":true,"grant_option":false,"name":"pg_create_subscription","superuser":false},{"execute":true,"grant_option":false,"name":"pg_database_owner","superuser":false},{"execute":true,"grant_option":false,"name":"pg_execute_server_program","superuser":false},{"execute":true,"grant_option":false,"name":"pg_maintain","superuser":false},{"execute":true,"grant_option":false,"name":"pg_monitor","superuser":false},{"execute":true,"grant_option":false,"name":"pg_read_all_data","superuser":false},{"execute":true,"grant_option":false,"name":"pg_read_all_settings","superuser":false},{"execute":true,"grant_option":false,"name":"pg_read_all_stats","superuser":false},{"execute":true,"grant_option":false,"name":"pg_read_server_files","superuser":false},{"execute":true,"grant_option":false,"name":"pg_signal_backend","superuser":false},{"execute":true,"grant_option":false,"name":"pg_stat_scan_tables","superuser":false},{"execute":true,"grant_option":false,"name":"pg_use_reserved_connections","superuser":false},{"execute":true,"grant_option":false,"name":"pg_write_all_data","superuser":false},{"execute":true,"grant_option":false,"name":"pg_write_server_files","superuser":false},{"execute":true,"grant_option":false,"name":"pgbouncer","superuser":false},{"execute":true,"grant_option":true,"name":"postgres","superuser":false},{"execute":true,"grant_option":false,"name":"service_role","superuser":false},{"execute":true,"grant_option":true,"name":"supabase_admin","superuser":true},{"execute":true,"grant_option":false,"name":"supabase_auth_admin","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_etl_admin","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_privileged_role","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_read_only_user","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_realtime_admin","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_replication_admin","superuser":false},{"execute":true,"grant_option":false,"name":"supabase_storage_admin","superuser":false},{"execute":true,"grant_option":false,"name":"verification_executor","superuser":false}],"security_definer":true,"signature":"onboard_tenant(text,text,text,text,uuid,text,text)"}]}'::jsonb THEN RAISE EXCEPTION 'identity precondition: exact core catalog drift'; END IF;
 -- CHANGE_BEGIN
 REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE public.users FROM anon, authenticated;
 -- USERS_REVOKED
 REVOKE EXECUTE ON FUNCTION public.create_onboarding_user(text,text,text) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.onboard_tenant(text,text,text,text,uuid,text,text) FROM PUBLIC, anon, authenticated;
