{"definition":"CHECK (role = ANY (ARRAY[''admin''::text, ''ktv_lead''::text, ''ktv''::text, ''admin_staff''::text, ''accountant''::text, ''hr''::text, ''student''::text, ''parent''::text]))","name":"users_role_check","type":"c"},{"definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id)","name":"users_tenant_id_fkey","type":"f"}],"functions":[{"acl":"{=X/supabase_auth_admin,postgres=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}","arguments":"","definition":"CREATE OR REPLACE FUNCTION auth.jwt()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n    coalesce(\n        nullif(current_setting(''request.jwt.claim'', true), ''''),\n        nullif(current_setting(''request.jwt.claims'', true), '''')\n    )::jsonb\n$function$\n","name":"jwt","owner":"supabase_auth_admin","proconfig":null,"schema":"auth","security_definer":false},{"acl":"{=X/supabase_auth_admin,supabase_auth_admin=X/supabase_auth_admin,dashboard_user=X/supabase_auth_admin}","arguments":"","definition":"CREATE OR REPLACE FUNCTION auth.uid()\n RETURNS uuid\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n  coalesce(\n    nullif(current_setting(''request.jwt.claim.sub'', true), ''''),\n    (nullif(current_setting(''request.jwt.claims'', true), '''')::jsonb ->> ''sub'')\n  )::uuid\n$function$\n","name":"uid","owner":"supabase_auth_admin","proconfig":null,"schema":"auth","security_definer":false},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.current_tenant_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT tenant_id FROM public.users WHERE id = auth.uid();\n$function$\n","name":"current_tenant_id","owner":"postgres","proconfig":null,"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.current_user_role()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT role FROM public.users WHERE id = auth.uid();\n$function$\n","name":"current_user_role","owner":"postgres","proconfig":null,"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE\n  v_tenant_id uuid;\nBEGIN\n  SELECT u.tenant_id INTO v_tenant_id\n  FROM public.users AS u\n  JOIN public.tenants AS t ON t.id = u.tenant_id\n  WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active'';\n\n  -- NULL would enable legacy policies using NULL as an unrestricted HQ sentinel.\n  IF v_tenant_id IS NULL THEN\n    RAISE EXCEPTION ''Active canonical identity and tenant required'' USING ERRCODE = ''42501'';\n  END IF;\n  RETURN v_tenant_id;\nEND;\n$function$\n","name":"get_auth_tenant_id","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.users AS u JOIN public.tenants AS t ON t.id = u.tenant_id\n    WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active'' AND u.role = ''admin''\n  );\n$function$\n","name":"is_admin","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.is_hq_super_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.users AS u JOIN public.tenants AS t ON t.id = u.tenant_id\n    WHERE u.id = auth.uid() AND u.status = ''active'' AND t.status = ''active''\n      AND u.role = ''admin'' AND t.product_key = ''bella_hq''\n  );\n$function$\n","name":"is_hq_super_admin","owner":"postgres","proconfig":["search_path=pg_catalog, public"],"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.log_audit_event()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    current_user_id UUID;\n    record_tenant_id UUID;\nBEGIN\n    BEGIN\n        current_user_id := auth.uid();\n    EXCEPTION WHEN OTHERS THEN\n        current_user_id := NULL;\n    END;\n    \n    BEGIN\n        IF TG_TABLE_NAME = ''tenants'' THEN\n            IF TG_OP = ''DELETE'' THEN\n                record_tenant_id := OLD.id;\n            ELSE\n                record_tenant_id := NEW.id;\n            END IF;\n        ELSE\n            IF TG_OP = ''DELETE'' THEN\n                record_tenant_id := OLD.tenant_id;\n            ELSE\n                record_tenant_id := NEW.tenant_id;\n            END IF;\n        END IF;\n    EXCEPTION WHEN OTHERS THEN\n        record_tenant_id := NULL;\n    END;\n\n    BEGIN\n        INSERT INTO public.audit_logs (\n            tenant_id,\n            table_name,\n            record_id,\n            action,\n            old_data,\n            new_data,\n            changed_by_id\n        ) VALUES (\n            record_tenant_id,\n            TG_TABLE_NAME,\n            COALESCE(NEW.id, OLD.id),\n            TG_OP,\n            CASE WHEN TG_OP IN (''UPDATE'', ''DELETE'') THEN row_to_json(OLD)::jsonb ELSE NULL END,\n            CASE WHEN TG_OP IN (''INSERT'', ''UPDATE'') THEN row_to_json(NEW)::jsonb ELSE NULL END,\n            current_user_id\n        );\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING ''audit_log_event failed for table % op %: %'', TG_TABLE_NAME, TG_OP, SQLERRM;\n    END;\n\n    IF TG_OP = ''DELETE'' THEN\n        RETURN OLD;\n    ELSE\n        RETURN NEW;\n    END IF;\nEND;\n$function$\n","name":"log_audit_event","owner":"postgres","proconfig":null,"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.sync_user_claims_to_auth()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  UPDATE auth.users\n  SET raw_app_meta_data = \n    coalesce(raw_app_meta_data, ''{}''::jsonb) || \n    jsonb_build_object(\n      ''role'', NEW.role,\n      ''tenant_id'', NEW.tenant_id\n    )\n  WHERE id = NEW.id;\n  RETURN NEW;\nEND;\n$function$\n","name":"sync_user_claims_to_auth","owner":"postgres","proconfig":null,"schema":"public","security_definer":true},{"acl":"{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  NEW.updated_at = NOW();\r\n  RETURN NEW;\r\nEND;\r\n$function$\n","name":"update_updated_at_column","owner":"postgres","proconfig":null,"schema":"public","security_definer":false}],"grants":[{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"SELECT"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"SELECT"},{"grantable":false,"grantee":"bella_developer","grantor":"postgres","privilege":"SELECT"},{"grantable":false,"grantee":"be