ID;\n  v_encrypted_password TEXT;\nBEGIN\n  -- Check if user already exists\n  SELECT id INTO v_user_id FROM auth.users WHERE email = p_email;\n  IF v_user_id IS NOT NULL THEN\n    RETURN v_user_id;\n  END IF;\n\n  -- Generate user ID\n  v_user_id := gen_random_uuid();\n  \n  -- Encrypt password with bcrypt\n  v_encrypted_password := crypt(p_password, gen_salt(''bf'', 10));\n\n  -- Insert into auth.users (excluding confirmed_at)\n  INSERT INTO auth.users (\n    instance_id,\n    id,\n    aud,\n    role,\n    email,\n    encrypted_password,\n    email_confirmed_at,\n    raw_app_meta_data,\n    raw_user_meta_data,\n    created_at,\n    updated_at\n  ) VALUES (\n    ''00000000-0000-0000-0000-000000000000''::uuid,\n    v_user_id,\n    ''authenticated'',\n    ''authenticated'',\n    p_email,\n    v_encrypted_password,\n    NOW(),\n    ''{\"provider\": \"email\", \"providers\": [\"email\"]}''::jsonb,\n    jsonb_build_object(''full_name'', p_full_name, ''email_verified'', true),\n    NOW(),\n    NOW()\n  );\n\n  -- Insert into auth.identities (excluding email)\n  INSERT INTO auth.identities (\n    id,\n    provider_id,\n    user_id,\n    identity_data,\n    provider,\n    last_sign_in_at,\n    created_at,\n    updated_at\n  ) VALUES (\n    gen_random_uuid(),\n    v_user_id::text,\n    v_user_id,\n    jsonb_build_object(''sub'', v_user_id::text, ''email'', p_email, ''email_verified'', true, ''phone_verified'', false),\n    ''email'',\n    NOW(),\n    NOW(),\n    NOW()\n  );\n\n  RETURN v_user_id;\nEND;\n$function$\n","grants":[{"grantable":false,"grantee":"bella_migration_executor","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}],"owner":"postgres","roles":[{"execute":false,"grant_option":false,"name":"anon","superuser":false},{"execute":false,"grant_option":false,"name":"authenticated","superuser":false},{"execute":false,"grant_option":false,"name":"authenticator","superuser":false},{"execute":false,"grant_option":false,"name":"bella_developer","superuser":false},{"execute":true,"grant_option":false,"name":"bella_migration_executor","superuser":false},{"execute":false,"grant_option":false,"name":"cli_login_postgres","superuser":false},{"execute":false,"grant_option":false,"name":"dashboard_user","superuser":false},{"execute":false,"grant_option":false,"name":"pg_checkpoint","superuser":false},{"execute":false,"grant_option":false,"name":"pg_create_subscription","superuser":false},{"execute":false,"grant_option":false,"name":"pg_database_owner","superuser":false},{"execute":false,"grant_option":false,"name":"pg_execute_server_program","superuser":false},{"execute":false,"grant_option":false,"name":"pg_maintain","superuser":false},{"execute":false,"grant_option":false,"name":"pg_monitor","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_data","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_settings","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_stats","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_server_files","superuser":false},{"execute":false,"grant_option":false,"name":"pg_signal_backend","superuser":false},{"execute":false,"grant_option":false,"name":"pg_stat_scan_tables","superuser":false},{"execute":false,"grant_option":false,"name":"pg_use_reserved_connections","superuser":false},{"execute":false,"grant_option":false,"name":"pg_write_all_data","superuser":false},{"execute":false,"grant_option":false,"name":"pg_write_server_files","superuser":false},{"execute":false,"grant_option":false,"name":"pgbouncer","superuser":false},{"execute":true,"grant_option":true,"name":"postgres","superuser":false},{"execute":true,"grant_option":false,"name":"service_role","superuser":false},{"execute":true,"grant_option":true,"name":"supabase_admin","superuser":true},{"execute":false,"grant_option":false,"name":"supabase_auth_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_etl_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_privileged_role","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_read_only_user","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_realtime_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_replication_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_storage_admin","superuser":false},{"execute":false,"grant_option":false,"name":"verification_executor","superuser":false}],"security_definer":true,"signature":"create_onboarding_user(text,text,text)"},{"acl":"{postgres=X/postgres,service_role=X/postgres,bella_migration_executor=X/postgres}","config":null,"definition":"CREATE OR REPLACE FUNCTION public.onboard_tenant(p_spa_name text, p_contact_phone text, p_address text, p_email text, p_admin_id uuid, p_admin_email text, p_admin_name text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_tenant_id UUID;\n    v_package_id UUID;\n    v_ktv_id UUID;\n    v_customer_id UUID;\n    v_booking_id UUID;\n    v_role_permissions JSONB;\n    v_salary_config JSONB;\n    v_coa_count INTEGER;\nBEGIN\n    -- 1. Check email duplicate\n    IF EXISTS (SELECT 1 FROM public.users WHERE email = p_admin_email) THEN\n        RAISE EXCEPTION ''Email % đã tồn tại trong hệ thống.'', p_admin_email;\n    END IF;\n\n    -- 2. Default configs (Updated to include ktv_lead, admin_staff, accountant, and hr)\n    v_role_permissions := ''{\"ktv_lead\": {\"dashboard\": true, \"customers\": false, \"bookings\": true, \"sessions\": true, \"chat\": true, \"crm\": true, \"services\": true, \"finance\": false, \"reconciliation\": false, \"inventory\": false, \"salary\": false, \"audit\": false, \"settings\": false},\n                            \"admin_staff\": {\"dashboard\": true, \"customers\": true, \"bookings\": true, \"sessions\": true, \"chat\": true, \"crm\": true, \"services\": true, \"inventory\": true, \"finance\": true, \"reconciliation\": false, \"salary\": false, \"audit\": false, \"settings\": false},\n                            \"accountant\": {\"dashboard\": true, \"customers\": false, \"bookings\": false, \"sessions\": false, \"chat\": false, \"crm\": false, \"services\": true, \"inventory\": true, \"finance\": true, \"reconciliation\": true, \"salary\": true, \"audit\": false, \"settings\": false},\n                            \"hr\": {\"dashboard\": true, \"customers\": false, \"bookings\": false, \"sessions\": true, \"chat\": false, \"crm\": false, \"services\": false, \"inventory\": false, \"finance\": false, \"reconciliation\": false, \"salary\": true, \"audit\": false, \"settings\": false}}''::jsonb;\n    v_salary_config := ''{\"bonus_5_star\": 50000, \"bonus_4_5_star\": 30000, \"bonus_4_star\": 10000, \"kpi_target_sessions\": 30, \"kpi_bonus_amount\": 1000000}''::jsonb;\n\n    -- 3. Create tenant\n    INSERT INTO public.tenants (\n        name, contact_phone, address, email, status, role_permissions, salary_config\n    )\n    VALUES (\n        p_spa_name, p_contact_phone, p_address, p_email, ''active'', v_role_permissions, v_salary_config\n    )\n    RETURNING id INTO v_tenant_id;\n\n    -- 4. Create admin user\n    INSERT INTO public.users (id, email, full_name, role, status, tenant_id)\n    VALUES (p_admin_id, p_admin_email, p_admin_name, ''admin'', ''active'', v_tenant_id);\n\n    -- 5. Seed sample package\n    INSERT INTO public.packages (\n        name, description, price, full_price, duration, total_sessions, ktv_commission, status, tenant_id\n    )\n    VALUES (\n        ''Massage Bầu VIP Nhật Bản'',\n        ''Gói chăm sóc massage bầu cao cấp theo liệu trình Nhật Bản giúp thư giãn cơ thể và giảm stress cho mẹ.'',\n        1200000, 1200000, ''90 phút/buổi'', 10, 150000, ''active'', v_tenant_id\n    )\n    RETURNING id INTO v_package_id;\n\n    -- 6. Seed sample KTV\n    v_ktv_id := uuid_generate_v4();\n    INSERT INTO public.users (id, email, full_name, role, status, tenant_id)\n    VALUES (\n        v_ktv_id,\n        ''ktv.mau.'' || substring(v_tenant_id::text from 1 for 8) || ''@bellaspa.com.vn'',\n        ''Trần Thị Mai (KTV Mẫu)'', ''ktv'', ''active'', v_tenant_id\n    );\n\n    -- 7. Seed sample customer\n    INSERT INTO public.customers (phone, name_mother, name_baby, dob_baby, address, status, tenant_id)\n    VALUES (\n        ''0987'' || substring(v_tenant_id::text from 1 for 6),\n        ''Phạm Thu Hương (Khách Mẫu)'', ''Bé Bơ'',\n        CURRENT_DATE - INTERVAL ''10 days'', p_address, ''active'', v_tenant_id\n    )\n    RETURNING id INTO v_customer_id;\n\n    -- 8. Seed sample booking\n    INSERT INTO public.bookings (\n        booking_number, customer_id, package_id, status, deposit_amount, full_price,\n        start_date, end_date, total_sessions, completed_sessions, contract_signed,\n        assigned_ktv_id, tenant_id\n    )\n    VALUES (\n        ''BK-'' || UPPER(substring(v_tenant_id::text from 1 for 5)),\n        v_customer_id, v_package_id, ''booked'', 200000, 1200000,\n        CURRENT_DATE, CURRENT_DATE + INTERVAL ''10 days'', 10, 0, TRUE,\n        v_ktv_id, v_tenant_id\n    )\n    RETURNING id INTO v_booking_id;\n\n    -- 9. Seed default Chart of Accounts (Thông tư 133)\n    BEGIN\n        v_coa_count := public.seed_default_coa(v_tenant_id);\n        RAISE NOTICE ''[onboard_tenant] Seeded % accounting accounts for tenant %'', v_coa_count, v_tenant_id;\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING ''[onboard_tenant] Failed to seed COA for tenant %: %'', v_tenant_id, SQLERRM;\n    END;\n\n    -- 10. Auto-create accounting period cho tháng hiện tại\n    BEGIN\n        PERFORM public.ensure_open_period(v_tenant_id, CURRENT_DATE);\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING ''[onboard_tenant] Failed to create accounting period for tenant %: %'', v_tenant_id, SQLERRM;\n    END;\n\n    RETURN v_tenant_id;\nEND;\n$function$\n","grants":[{"grantable":false,"grantee":"bella_migration_executor","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE"}],"owner":"postgres","roles":[{"execute":false,"grant_option":false,"name":"anon","superuser":false},{"execute":false,"grant_option":false,"name":"authenticated","superuser":false},{"execute":false,"grant_option":false,"name":"authenticator","superuser":false},{"execute":false,"grant_option":false,"name":"bella_developer","superuser":false},{"execute":true,"grant_option":false,"name":"bella_migration_executor","superuser":false},{"execute":false,"grant_option":false,"name":"cli_login_postgres","superuser":false},{"execute":false,"grant_option":false,"name":"dashboard_user","superuser":false},{"execute":false,"grant_option":false,"name":"pg_checkpoint","superuser":false},{"execute":false,"grant_option":false,"name":"pg_create_subscription","superuser":false},{"execute":false,"grant_option":false,"name":"pg_database_owner","superuser":false},{"execute":false,"grant_option":false,"name":"pg_execute_server_program","superuser":false},{"execute":false,"grant_option":false,"name":"pg_maintain","superuser":false},{"execute":false,"grant_option":false,"name":"pg_monitor","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_data","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_settings","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_all_stats","superuser":false},{"execute":false,"grant_option":false,"name":"pg_read_server_files","superuser":false},{"execute":false,"grant_option":false,"name":"pg_signal_backend","superuser":false},{"execute":false,"grant_option":false,"name":"pg_stat_scan_tables","superuser":false},{"execute":false,"grant_option":false,"name":"pg_use_reserved_connections","superuser":false},{"execute":false,"grant_option":false,"name":"pg_write_all_data","superuser":false},{"execute":false,"grant_option":false,"name":"pg_write_server_files","superuser":false},{"execute":false,"grant_option":false,"name":"pgbouncer","superuser":false},{"execute":true,"grant_option":true,"name":"postgres","superuser":false},{"execute":true,"grant_option":false,"name":"service_role","superuser":false},{"execute":true,"grant_option":true,"name":"supabase_admin","superuser":true},{"execute":false,"grant_option":false,"name":"supabase_auth_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_etl_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_privileged_role","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_read_only_user","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_realtime_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_replication_admin","superuser":false},{"execute":false,"grant_option":false,"name":"supabase_storage_admin","superuser":false},{"execute":false,"grant_option":false,"name":"verification_executor","superuser":false}],"security_definer":true,"signature":"onboard_tenant(text,text,text,text,uuid,text,text)"}]}'::jsonb THEN RAISE EXCEPTION 'identity postcondition: exact expected ACL/effective privilege mismatch'; END IF;
 SELECT evidence INTO outside_after FROM (WITH outside_relations AS (SELECT n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,c.relacl::text AS acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth') AND c.oid<>'public.users'::regclass), all_policies AS(SELECT * FROM pg_policies WHERE schemaname IN ('public','auth')), other_functions AS(SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) AS args,p.prosecdef,pg_get_userbyid(p.proowner) AS owner,p.proacl::text AS acl,p.proconfig,md5(pg_get_functiondef(p.oid)) AS definition_hash FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth') AND p.prokind='f' AND NOT(p.oid=ANY(ARRAY['public.create_onboarding_user(text,text,text)'::regprocedure,'public.onboard_tenant(text,text,text,text,uuid,text,text)'::regprocedure]))) SELECT jsonb_build_object('outside_relations_count',(SELECT count(*) FROM outside_relations),'outside_relation_hash',(SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY nspname,relname)::text) FROM outside_relations r),'all_policy_hash',(SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname)::text) FROM all_policies p),'other_function_hash',(SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY nspname,proname,args)::text) FROM other_functions f),'full_membership_hash',(SELECT md5(jsonb_agg(to_jsonb(m) ORDER BY roleid,member,grantor)::text) FROM pg_auth_members m),'full_role_hash',(SELECT md5(jsonb_agg((to_jsonb(r)-'rolvaliduntil') ORDER BY rolname)::text) FROM pg_roles r),'schema_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname)::text) FROM pg_namespace WHERE nspname NOT LIKE 'pg_temp_%' AND nspname NOT LIKE 'pg_toast_temp_%'),'default_acl_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY oid)::text,'[]')) FROM pg_default_acl a)) AS evidence) o;
 IF outside_after IS DISTINCT FROM outside_before THEN RAISE EXCEPTION 'identity postcondition: out-of-scope catalog changed'; END IF;
END;
$identity_containment$;
